const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "<h3>Artículos</h3> <div class=\"artikuli-info items-intro-info\"> <span class=\"artikuli-info-icon\">i</span> <div>El article alemán no siempre coincide con el sistema de género inglés. Por lo tanto, es mejor aprender los sustantivos junto con el article.</div> </div> <section class=\"artikuli-block\"> <h4 class=\"artikuli-header\"><span>•</span>Ejemplos de artículos</h4> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">der Tisch - table</div> <div class=\"kurss-example\">die Tür - la puerta</div> <div class=\"kurss-example\">das Messer - cuchillo</div> <div class=\"kurss-example\">das Mädchen - niña</div> </div> </section> <section class=\"artikuli-block\"> <h4 class=\"artikuli-header\"><span>♂</span>A menudo DER</h4> <p class=\"artikuli-explain\">DER suele ser personas masculinas, días, meses, estaciones y algunas palabras con determinadas terminaciones.</p> <h5 class=\"artikuli-subtitle\">Términos</h5> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">-er → a menudo DER, por ejemplo: der Computer, der Lehrer <span class=\"artikuli-note\">pero no siempre</span></div> <div class=\"kurss-example\">-ling → a menudo DER, por ejemplo: der Schmetterling</div> <div class=\"kurss-example\">-ismus → a menudo DER, por ejemplo: der Tourismus, der Kapitalismus</div> <div class=\"kurss-example\">personas masculinas → der Mann, der Vater</div> <div class=\"kurss-example\">profesiones → der Lehrer, der Arzt</div> <div class=\"kurss-example\">marcas de automóviles → adecuado para BMW, adecuado para Mercedes</div> <div class=\"kurss-example\">días → der Montag, der Dienstag</div> <div class=\"kurss-example\">meses → der agosto, der diciembre</div> <div class=\"kurss-example\">Estaciones → der Sommer, der Winter</div> </div> <h5 class=\"artikuli-subtitle\">Ejemplos</h5> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">der Mann - man</div> <div class=\"kurss-example\">der Vater - padre</div> <div class=\"kurss-example\">se adapta de lunes a lunes</div> <div class=\"kurss-example\">se adapta a agosto - agosto</div> <div class=\"kurss-example\">der Sommer - verano</div> <div class=\"kurss-example\">der Lehrer - profesor</div> <div class=\"kurss-example\">der Computer - computer</div> <div class=\"kurss-example\">der Schmetterling - mariposa</div> </div> </section> <section class=\"artikuli-block\"> <h4 class=\"artikuli-header\"><span>♀</span>A menudo DIE</h4> <p class=\"artikuli-explain\">DIE es a menudo una persona femenina, plural y palabras que terminan en -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p> <h5 class=\"artikuli-subtitle\">Términos</h5> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div> <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div> <div class=\"kurss-example\">-keit → die Möglichkeit</div> <div class=\"course-example\">-schaft → die Mannschaft</div> <div class=\"course-example\">-ion → die Nation</div> <div class=\"course-example\">-tät → die Universität</div> <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div> <div class=\"kurss-example\">personas femeninas → die Frau, die Mutter</div> <div class=\"kurss-example\">marcas de motocicletas → la Harley-Davidson, la Yamaha</div> <div class=\"kurss-example\">plural → los automóviles, la casa</div> <div class=\"kurss-example\">plural casi siempre → die Autos, die Häuser, die Kinder</div> </div> <h5 class=\"artikuli-subtitle\">Ejemplos</h5> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">die Frau - mujer</div> <div class=\"kurss-example\">die Mutter - madre</div> <div class=\"kurss-example\">die Wohnung - apartamento</div> <div class=\"kurss-example\">die Rechnung - factura</div> <div class=\"kurss-example\">die Freiheit - libertad</div> <div class=\"kurss-example\">die Möglichkeit - oportunidad</div> <div class=\"kurss-example\">die Mannschaft - el equipo</div> <div class=\"kurss-example\">die Nation - nación</div> <div class=\"kurss-example\">die Universität - la universidad</div> <div class=\"kurss-example\">die Polizei - la policía</div> </div> </section> <section class=\"artikuli-block\"> <h4 class=\"artikuli-header\"><span>◇</span>A menudo DAS</h4> <p class=\"artikuli-explain\">DAS suelen tener diminutivos con -chen / -lein, muchas palabras con -ment / -um y verbos como sustantivos.</p> <h5 class=\"artikuli-subtitle\">Términos</h5> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div> <div class=\"kurss-example\">-lein → das Fräulein</div> <div class=\"kurss-example\">-ment → das Instrument</div> <div class=\"kurss-example\">-um → das Zentrum, das Museum</div> <div class=\"kurss-example\">metales → das Gold, das Silber, das Eisen</div> <div class=\"kurss-example\">elementos químicos → das Eisen, das Sauerstoff</div> <div class=\"kurss-example\">hoteles → das Hotel</div> <div class=\"kurss-example\">colores como sustantivos → das Rot, das Blau</div> <div class=\"kurss-example\">verbo como sustantivo → das Essen, das Lernen</div> <div class=\"kurss-example\">verbos como sustantivos → das Essen, das Lernen, das Lesen</div> </div> <h5 class=\"artikuli-subtitle\">Ejemplos</h5> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">das Kind - niño</div> <div class=\"kurss-example\">das Mädchen - niña</div> <div class=\"kurss-example\">das Häuschen - la cabaña</div> <div class=\"kurss-example\">das Instrument - instrumento</div> <div class=\"kurss-example\">das Zentrum - centro</div> <div class=\"kurss-example\">das Museum - museo</div> <div class=\"kurss-example\">das Essen - comer / comida</div> <div class=\"course-example\">das Lernen - Aprender</div> </div> </section> <section class=\"artikuli-block\"> <h4 class=\"artikuli-header\"><span>!</span>Excepciones importantes / debe aprender con el article</h4> <p class=\"artikuli-explain\">Para algunas palabras, el article no se puede determinar de manera confiable por la terminación o el origen letón. Es mejor estudiarlos junto con el article.</p> <div class=\"artikuli-grid\"> <div class=\"kurss-example\">die Tür - la puerta</div> <div class=\"kurss-example\">das Messer - el cuchillo</div> <div class=\"kurss-example\">die Sonne - el sol</div> <div class=\"kurss-example\">der Mond - la luna</div> <div class=\"kurss-example\">das Mädchen - niña</div> <div class=\"kurss-example\">das Auto - coche</div> <div class=\"kurss-example\">der Käse - queso</div> <div class=\"kurss-example\">die Gabel - fork</div> </div> </section> <div class=\"artikuli-info items-bottom-info\"> <span class=\"artikuli-info-icon\">i</span> <div>Ayuda para terminaciones y grupos de palabras adivinar el article, pero no son una regla 100% segura. Si no está seguro, aprenda la palabra junto con el article.</div> </div>",
  "kurssPronounsLesson": "\n  <h3>Pronombres</h3> <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativo, acusativo y dativo: formas de los pronombres.</div>\n  </div> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativo: ¿quién? / ¿qué?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich - yo</div><div class=\"kurss-example\">du - tú</div><div class=\"kurss-example\">er - él</div><div class=\"kurss-example\">sie - ella</div><div class=\"kurss-example\">es - ello</div><div class=\"kurss-example\">wir - nosotros</div><div class=\"kurss-example\">ihr - vosotros/vosotras</div><div class=\"kurss-example\">sie - ellos/ellas</div><div class=\"kurss-example\">Sie - usted/ustedes (cortesía)</div></div>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Acusativo: ¿a quién? / ¿qué?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich - me</div><div class=\"kurss-example\">dich - te</div><div class=\"kurss-example\">ihn - lo (masculino)</div><div class=\"kurss-example\">sie - la (femenino)</div><div class=\"kurss-example\">es - lo</div><div class=\"kurss-example\">uns - nos</div><div class=\"kurss-example\">euch - os</div><div class=\"kurss-example\">sie - los/las</div><div class=\"kurss-example\">Sie - lo/la/los/las (cortesía)</div></div>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativo: ¿a quién?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir - me</div><div class=\"kurss-example\">dir - te</div><div class=\"kurss-example\">ihm - le (masculino/neutro)</div><div class=\"kurss-example\">ihr - le (femenino)</div><div class=\"kurss-example\">uns - nos</div><div class=\"kurss-example\">euch - os</div><div class=\"kurss-example\">ihnen - les</div><div class=\"kurss-example\">Ihnen - le/les (cortesía)</div></div>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>¿Cómo elegir la forma correcta?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativo</span> - sujeto de la oración (¿quién lo hace?)</li><li>Acusativo - objeto directo (¿a quién? / ¿qué?)</li><li><span class=\"case-green\">Dativo</span> - objeto indirecto (¿a quién?)</li></ul>\n  </section> \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Ejemplos</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Te veo.</div><div class=\"kurss-example\">Ich sehe ihn. — Lo veo.</div><div class=\"kurss-example\">Wir mögen euch. — Nos gustáis.</div><div class=\"kurss-example\">Ich helfe dir. — Te ayudo.</div><div class=\"kurss-example\">Ich gebe ihm ein Buch. — Le doy un libro.</div><div class=\"kurss-example\">Wir danken euch. — Os damos las gracias.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>El nominativo marca el sujeto; el acusativo suele marcar el objeto directo y el dativo, el objeto indirecto. Observe la función del pronombre en la oración.</div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vocales: largas y cortas</h3>\n            <p class=\"kurss-lesson-intro\">En alemán, las vocales pueden ser largas o cortas. Esto influye en la pronunciación de la palabra.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocal larga</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — cálido</div><div class=\"kurss-example\">gut (gūt) — bueno</div><div class=\"kurss-example\">Tat (tāt) — trabajo / acción</div><div class=\"kurss-example\">Flur (flūr) — pasillo</div><div class=\"kurss-example\">Weg (vēk) — camino</div><div class=\"kurss-example\">Hut (hūt) — sombrero</div><div class=\"kurss-example\">Hof (hōf) — patio</div><div class=\"kurss-example\">Schlaf (šlāf) — sueño</div></div>\n              <p>Si después de una vocal aparece una sola consonante, la vocal suele pronunciarse larga.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocal corta</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — hongo</div><div class=\"kurss-example\">Wort (vort) — palabra</div><div class=\"kurss-example\">Mund (munt) — boca</div><div class=\"kurss-example\">bald (balt) — pronto</div><div class=\"kurss-example\">scharf (šarf) — afilado</div><div class=\"kurss-example\">Feld (felt) — campo</div><div class=\"kurss-example\">voll (fol) — lleno</div></div>\n              <p>Si después de una vocal aparecen dos o más consonantes, la vocal suele pronunciarse corta.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminaciones -en / -el / -er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — cantar</div><div class=\"kurss-example\">tragen (trāgen) — llevar</div><div class=\"kurss-example\">Garten (garten) — jardín</div><div class=\"kurss-example\">Vogel (fōgel) — pájaro</div><div class=\"kurss-example\">Segel (zēgel) — vela</div><div class=\"kurss-example\">Braten (brāten) — asado</div><div class=\"kurss-example\">Bogen (bōgen) — arco</div><div class=\"kurss-example\">Spiegel (špīgel) — espejo</div><div class=\"kurss-example\">Finger (finger) — dedo</div><div class=\"kurss-example\">Halter (halter) — soporte</div><div class=\"kurss-example\">Arbeiter (arbaiter) — trabajador</div><div class=\"kurss-example\">Häuser (hoizer) — casas</div><div class=\"kurss-example\">wieder (vīder) — otra vez</div><div class=\"kurss-example\">breiter (braiter) — más ancho</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>La letra h como señal de longitud</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — marco</div><div class=\"kurss-example\">Ohr (ōr) — oreja</div><div class=\"kurss-example\">Kohle (kōle) — carbón</div><div class=\"kurss-example\">Zahl (cāl) — número</div><div class=\"kurss-example\">ihn (īn) — lo</div><div class=\"kurss-example\">ihm (īm) — a él</div><div class=\"kurss-example\">Huhn (hūn) — gallina</div><div class=\"kurss-example\">nahm (nām) — tomó</div><div class=\"kurss-example\">nehmen (nēmen) — tomar</div><div class=\"kurss-example\">Schuh (šū) — zapato</div></div>\n              <p>En algunas palabras, la h alarga la vocal anterior. En estos casos, normalmente no se pronuncia.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminaciones en -e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lámpara</div><div class=\"kurss-example\">Hase (hāze) — liebre</div><div class=\"kurss-example\">Knabe (knābe) — niño</div><div class=\"kurss-example\">Rabe (rābe) — cuervo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>La i larga = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — artículo «die»</div><div class=\"kurss-example\">diese (dīze) — esta / estos</div><div class=\"kurss-example\">wieder (vīder) — otra vez</div><div class=\"kurss-example\">Fliege (flīge) — mosca</div><div class=\"kurss-example\">Ziege (cīge) — cabra</div><div class=\"kurss-example\">Stiel (štīl) — tallo</div><div class=\"kurss-example\">Dieb (dīp) — ladrón</div><div class=\"kurss-example\">hier (hīr) — aquí</div></div>\n              <p>En alemán, la i larga suele escribirse como ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocales dobles</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zāl) — sala</div><div class=\"kurss-example\">Saat (zāt) — siembra</div><div class=\"kurss-example\">Staat (štāt) — Estado</div><div class=\"kurss-example\">Beere (bēre) — baya</div><div class=\"kurss-example\">See (zē) — lago / mar</div><div class=\"kurss-example\">Beet (bēt) — bancal</div><div class=\"kurss-example\">Boot (bōt) — barco</div><div class=\"kurss-example\">Moor (mōr) — pantano</div><div class=\"kurss-example\">Moos (mōs) — musgo</div></div>\n              <p>Las vocales dobles normalmente se pronuncian largas.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — pared</div><div class=\"kurss-example\">Wände (vende) — paredes</div><div class=\"kurss-example\">Vater (fāter) — padre</div><div class=\"kurss-example\">Väter (fēter) — padres</div><div class=\"kurss-example\">Schrank (šrank) — armario</div><div class=\"kurss-example\">Schränke (šrenke) — armarios</div><div class=\"kurss-example\">Bank (bank) — banco / banquillo</div><div class=\"kurss-example\">Bänke (benke) — bancos / banquillos</div><div class=\"kurss-example\">Tal (tāl) — valle</div><div class=\"kurss-example\">Täler (tēler) — valles</div></div>\n              <p>La ä es la vocal con diéresis derivada de a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — rosa</div><div class=\"kurss-example\">Röschen (rēschen) — rosita</div><div class=\"kurss-example\">Ofen (ōfen) — horno</div><div class=\"kurss-example\">Öfen (ēfen) — hornos</div><div class=\"kurss-example\">Rock (rok) — falda</div><div class=\"kurss-example\">Röcke (röke) — faldas</div></div>\n              <p>La ö es la vocal con diéresis derivada de o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (kurc) — corto</div><div class=\"kurss-example\">kürzer (kürcer) — más corto</div><div class=\"kurss-example\">Kunst (kunst) — arte</div><div class=\"kurss-example\">Künste (künste) — artes</div><div class=\"kurss-example\">Mutter (muter) — madre</div><div class=\"kurss-example\">Mütter (müter) — madres</div></div>\n              <p>La ü es la vocal con diéresis derivada de u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diptongos: au y äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — árbol</div><div class=\"kurss-example\">Bäume (boime) — árboles</div><div class=\"kurss-example\">Haus (haus) — casa</div><div class=\"kurss-example\">Häuser (hoizer) — casas</div><div class=\"kurss-example\">Strauch (štrauh) — arbusto</div><div class=\"kurss-example\">Sträucher (štroiher) — arbustos</div><div class=\"kurss-example\">Maus (maus) — ratón</div><div class=\"kurss-example\">Mäuse (moize) — ratones</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diptongos: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — hoy</div><div class=\"kurss-example\">Leute (loite) — gente</div><div class=\"kurss-example\">neu (noi) — nuevo</div><div class=\"kurss-example\">neun (noin) — nueve</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diptongos: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — mío</div><div class=\"kurss-example\">dein (dain) — tuyo</div><div class=\"kurss-example\">sein (zain) — suyo / suya / ser</div><div class=\"kurss-example\">frei (frai) — libre</div><div class=\"kurss-example\">arbeiten (arbaiten) — trabajar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Notas de pronunciación de la lección 2</h4>\n              <ul class=\"kurss-summary-list\"><li>En las palabras ich, nicht, rechnen y zeichnen, «ch» se pronuncia de forma suave.</li><li>En las palabras arbeiten y zeichnen, «ei» se pronuncia como «ai».</li><li>«sp» al principio de una palabra se pronuncia como «šp».</li><li>En el verbo tun, la letra «u» se pronuncia larga.</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Resumen</h4>\n              <ul class=\"kurss-summary-list\"><li>Una consonante después de una vocal → la vocal suele ser larga.</li><li>Dos o más consonantes después de una vocal → la vocal suele ser corta.</li><li>La h puede alargar una vocal.</li><li>ie suele representar una i larga.</li><li>Las vocales dobles normalmente son largas.</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Consonantes y combinaciones de letras</h3>\n            <p class=\"kurss-lesson-intro\">En alemán, algunas consonantes y combinaciones de letras se pronuncian de forma diferente a como se escriben. Esta lección contiene los ejemplos más importantes para principiantes.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Consonantes finales</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — rueda</div><div class=\"kurss-example\">die Räder (rēder) — ruedas</div><div class=\"kurss-example\">Bad (bāt) — baño</div><div class=\"kurss-example\">Bäder (bēder) — baños</div></div>\n              <p>Al final de una palabra, las consonantes sonoras b, d y g suelen pronunciarse como p, t y k.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>«ch» tiene dos pronunciaciones principales: una suave después de e, i, ä, ö y ü, y otra más fuerte después de a, o, u y au.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — calcular</div><div class=\"kurss-example\">zeichnen (caihnen) — dibujar</div><div class=\"kurss-example\">nicht (niht) — no</div><div class=\"kurss-example\">schlecht (šleht) — malo</div><div class=\"kurss-example\">mich (mih) — me / a mí</div><div class=\"kurss-example\">dich (dih) — te / a ti</div><div class=\"kurss-example\">Strauch (štrauh) — arbusto</div><div class=\"kurss-example\">noch (noh) — todavía</div><div class=\"kurss-example\">Nacht (najt) — noche</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>«sch» se pronuncia como el sonido «sh»; en la transcripción simplificada se representa como «š».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (šūle) — escuela</div><div class=\"kurss-example\">Schüler (šūler) — alumno</div><div class=\"kurss-example\">Schiff (šif) — barco</div><div class=\"kurss-example\">Schraube (šraube) — tornillo</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp y st al principio de palabra</h4>\n              <p>Al principio de una palabra o sílaba, «sp» suele pronunciarse como «šp» y «st» como «št».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (špīlen) — jugar</div><div class=\"kurss-example\">Sprung (šprung) — salto</div><div class=\"kurss-example\">stehen (štēen) — estar de pie</div><div class=\"kurss-example\">Stall (štal) — establo</div><div class=\"kurss-example\">Stand (štant) — posición / puesto</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>En alemán, «qu» normalmente se pronuncia como «kv».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvāl) — tormento</div><div class=\"kurss-example\">Quartier (kvartīr) — barrio / alojamiento</div><div class=\"kurss-example\">quer (kvēr) — transversalmente</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s y z</h4>\n              <p>Al principio de una palabra, la «s» suele sonar como una «z» sonora. La «z» alemana se pronuncia como «ts».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāgen) — decir</div><div class=\"kurss-example\">singen (zingen) — cantar</div><div class=\"kurss-example\">Rose (rōze) — rosa</div><div class=\"kurss-example\">Zahl (tsāl) — número</div><div class=\"kurss-example\">Zeit (tsait) — tiempo</div><div class=\"kurss-example\">Zink (tsink) — cinc</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>En alemán, la «v» suele pronunciarse como «f». En palabras de origen extranjero, suele sonar como «v».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — padre</div><div class=\"kurss-example\">von (fon) — de</div><div class=\"kurss-example\">viel (fīl) — mucho</div><div class=\"kurss-example\">vier (fīr) — cuatro</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klavīr) — piano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x e y</h4>\n              <p>La «x» se pronuncia como «ks». En algunas palabras, la «y» se pronuncia como la vocal alemana «ü».</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēliks) — Félix</div><div class=\"kurss-example\">Axt (akst) — hacha</div><div class=\"kurss-example\">Mystik (müstik) — misticismo</div><div class=\"kurss-example\">Nyx (nüks) — Nix</div><div class=\"kurss-example\">Mythe (müte) — mito</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>La letra «ß» se pronuncia como una «s» sorda.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — pie</div><div class=\"kurss-example\">Füße (fūse) — pies</div><div class=\"kurss-example\">Grüße (grūse) — saludos</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Resumen</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → š</li><li>sp / st al principio → šp / št</li><li>qu → kv</li><li>z → ts</li><li>v suele pronunciarse como f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "<h3>Conceptos básicos de los verbos</h3> <p class=\"kurss-lesson-intro\">1. verbos y conjugaciones de la conferencia.</p> <section class=\"course-lesson-section\"> <h4>Verbos</h4> <div class=\"course-examples\"><div class=\"course-example\">kommen - venir</div><div class=\"course-example\">gehen - ir</div><div class=\"course-example\">stehen - estar de pie</div><div class=\"course-example\">singen - to cantar</div></div> </section> <section class=\"curso-lección-sección\"> <h4>kommen</h4> <div class=\"course-example\"><div class=\"course-example\">ich komme - yo vengo</div><div class=\"course-example\">du kommst - tú vienes</div><div class=\"course-example\">er kommt - él viene</div><div class=\"course-example\">sie kommt - ella viene</div><div class=\"course-example\">wir kommen - nosotros venimos</div><div class=\"course-example\">ihr kommt - tú vienes</div><div class=\"kurss-example\">kommen — ellos / ellos vienen</div></div> </section> <section class=\"course-lesson-section\"> <h4>gehen</h4> <div class=\"course-example\"><div class=\"course-example\">ich gehe - yo voy</div><div class=\"course-example\">du gehst - tú vas</div><div class=\"course-example\">er geht - él va</div><div class=\"course-example\">sie geht - ella va</div><div class=\"course-example\">wir gehen - nosotros vamos</div><div class=\"course-example\">ihr geht - tú vas</div><div class=\"kurss-example\">gehen — ellos / ella va</div></div> </section> <section class=\"course-lesson-section\"> <h4>stehen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich stehe - yo estoy de pie</div><div class=\"course-example\">du stehst - tú estás de pie</div><div class=\"course-example\">er steht - él está de pie</div><div class=\"course-example\">sie steht - ella está de pie</div><div class=\"course-example\">wir stehen - nosotros estamos de pie</div><div class=\"course-example\">ihr steht - tú estás de pie</div><div class=\"kurss-example\">stehen — ellos / ella se para</div></div> </section> <section class=\"course-lesson-section\"> <h4>canta</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">singen — yo canto</div><div class=\"kurss-example\">ich komme — tú cantas</div><div class=\"kurss-example\">du kommst — él canta</div><div class=\"kurss-example\">er kommt — ella canta</div><div class=\"kurss-example\">sie kommt — nosotros cantamos</div><div class=\"kurss-example\">wir kommen — tú cantas</div><div class=\"kurss-example\">ihr kommt — ellos / ellos cantan</div></div> </section> <section class=\"course-lesson-section\"> <h4>2. verbos de conferencia</h4> <div class=\"course-example\"><div class=\"course-example\">spielen - jugar</div><div class=\"course-example\">arbeiten - trabajar</div><div class=\"course-example\">fragen - preguntar</div><div class=\"course-example\">antworten - responder</div><div class=\"course-example\">rechnen - calcular</div><div class=\"course-example\">zeichnen - dibujar</div><div class=\"course-example\">tun - hacer</div></div> </section> <section class=\"course-lesson-section\"> <h4>jugar</h4> <div class=\"course-examples\"><div class=\"course-example\">ich spielt - Yo juego</div><div class=\"course-example\">du spielst - tú juegas</div><div class=\"course-example\">er spielt - él juega</div><div class=\"course-example\">sie spielt - ella juega</div><div class=\"course-example\">wir spielen - nosotros jugamos</div><div class=\"course-example\">ihr spielt - tú juegas</div><div class=\"kurss-example\">sie kommen — ellos / ella en el juego</div></div> </section> <section class=\"course-lesson-section\"> <h4>arbeiten</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — yo trabajo</div><div class=\"kurss-example\">du gehst — tú trabajas</div><div class=\"kurss-example\">er geht — él trabaja</div><div class=\"kurss-example\">sie geht — ella trabaja</div><div class=\"kurss-example\">wir gehen — nosotros trabajamos</div><div class=\"kurss-example\">ihr geht — tú trabajas</div><div class=\"kurss-example\">sie gehen — ellos / ella trabajan</div></div> </section> <section class=\"course-lesson-section\"> <h4>fragen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich frage - te pregunto</div><div class=\"course-example\">du fragst - tú pregunta</div><div class=\"course-example\">er fragt - él pregunta</div><div class=\"course-example\">sie fragt - ella pregunta</div><div class=\"course-example\">wir fragen - nosotros preguntamos</div><div class=\"course-example\">ihr fragt - tú preguntas</div><div class=\"kurss-example\">ich stehe — ellos / ellos preguntan</div></div> </section> <section class=\"course-lesson-section\"> <h4>respuesta</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">du stehst — Yo respondo</div><div class=\"kurss-example\">er steht — tú respondes</div><div class=\"kurss-example\">sie steht — él responde</div><div class=\"kurss-example\">wir stehen — ella responde</div><div class=\"kurss-example\">ihr steht — nosotros respondemos</div><div class=\"kurss-example\">sie stehen — tú respondes</div><div class=\"kurss-example\">ich singe — ellos/ellos responden</div></div> </section> <section class=\"course-lesson-section\"> <h4>rechnen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich rechne - yo calculo</div><div class=\"course-example\">du rechnest - tú calcula</div><div class=\"course-example\">er rechnet - él calcula</div><div class=\"course-example\">sie rechnet - su cálculo</div><div class=\"course-example\">wir rechnen - nosotros calculamos</div><div class=\"kurss-example\">du singst — tú calcula</div><div class=\"kurss-example\">er singt — ellos / ella factura</div></div> </section> <section class=\"course-lesson-section\"> <h4>zeichnen</h4> <div class=\"course-examples\"><div class=\"course-example\">ich zeichne - yo dibujo</div><div class=\"course-example\">du zeichnest - tú dibujas</div><div class=\"course-example\">er zeichnet - él dibuja</div><div class=\"course-example\">sie zeichnet - ella dibuja</div><div class=\"course-example\">wir zeichnen - nosotros dibujamos</div><div class=\"course-example\">ihr zeichnet - tú tú dibuja</div><div class=\"kurss-example\">sie singt — ellos / ella dibuja</div></div> </section> <section class=\"course-lesson-section\"> <h4>allí</h4> <div class=\"course-examples\"><div class=\"course-example\">ich tue - yo hago</div><div class=\"course-example\">du tust - tú haces</div><div class=\"course-example\">er tut - él lo hace</div><div class=\"course-example\">sie tut - ella lo hace</div><div class=\"course-example\">wir tun - nosotros lo hacemos</div><div class=\"course-example\">ihr tut - tú lo haces</div><div class=\"kurss-example\">wir singen — ellos / ellos lo hacen</div></div> </section>",
  "kurssSentenceStructureLesson": "<h3>Estructura de la oración</h3> <p class=\"kurss-lesson-intro\">En una oración interrogativa, el verbo suele aparecer primero en alemán.</p> <section class=\"course-lesson-section\"> <h4>Ejemplos</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Ya vienes.</div><div class=\"kurss-example\">Kommst du? — ¿Vienes?</div><div class=\"kurss-example\">Er singt. — Él canta.</div><div class=\"kurss-example\">Singt er? — ¿Canta?</div><div class=\"kurss-example\">Stehst du? — ¿Estás de pie?</div><div class=\"kurss-example\">Ja, ich stehe. — Sí, estoy de pie.</div><div class=\"kurss-example\">Geht ihr? — ¿Vas a ir?</div><div class=\"kurss-example\">Ja, wir gehen. — Sí, vamos.</div></div> </section> <section class=\"course-lesson-section\"> <h4>Preguntas con “was”</h4> <p>Si una pregunta comienza con una palabra interrogativa, el verbo en alemán suele ir inmediatamente después de la palabra interrogativa.</p> <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — ¿Qué estás haciendo?</div><div class=\"kurss-example\">Was tut er? — ¿Qué está haciendo?</div><div class=\"kurss-example\">Was tut sie? — ¿Qué está haciendo?</div><div class=\"kurss-example\">Was tun sie? — ¿Qué están haciendo?</div></div> </section> <section class=\"course-lesson-section\"> <h4>Negación con “nicht”</h4> <p>Cuando la negación \"nicht\" se refiere a un verbo, normalmente va después del verbo en alemán.</p> <div class=\"course-examples\"><div class=\"course-example\">Ich spiele nicht. — No juego.</div><div class=\"kurss-example\">Ich spiele nicht. — Paul no pregunta.</div><div class=\"kurss-example\">Paul fragt nicht. — No viene.</div><div class=\"kurss-example\">Er kommt nicht. — Ellos/ellos no cantan.</div></div> </section> <section class=\"course-lesson-section\"> <h4>Oraciones de la lección 2</h4> <div class=\"kurss-examples\"><div class=\"kurss-example\">Sie singen nicht. — ¿Juegas?</div><div class=\"kurss-example\">Spielst du? — No, no juego, trabajo.</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Paul no pregunta, trabaja.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — ¿Trabajas?</div><div class=\"kurss-example\">Arbeitest du? — No, no estoy trabajando, estoy cantando.</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — ¿Qué está haciendo Paul?</div><div class=\"kurss-example\">Was tut Paul? — Está jugando.</div><div class=\"kurss-example\">Er spielt. — ¿Qué está haciendo María?</div><div class=\"kurss-example\">Was tut Marie? — Ella canta.</div><div class=\"kurss-example\">Sie singt. — Paul toca, pero María canta.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — ¿Cantas?</div><div class=\"kurss-example\">Singt ihr? — No, no cantamos, trabajamos.</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — ¿Qué están haciendo Paul y María?</div><div class=\"kurss-example\">Was tun Paul und Marie? — Preguntan.</div><div class=\"kurss-example\">Sie fragen. — No contestan.</div><div class=\"kurss-example\">Sie antworten nicht. — ¿Quién trabaja?</div><div class=\"kurss-example\">Wer arbeitet? — Trabajamos.</div><div class=\"kurss-example\">Wir arbeiten. — Nosotros contar y dibujar.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Vienen, preguntan, responden, trabajan, juegan, cantan y se van.</div></div> </section>",
  "kurssLesson2": "<h3>Lección 2</h3> <p class=\"kurss-lesson-intro\">Segunda lección: diálogos, palabras, pronunciación, gramática y traducción.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div> <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div> <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div> <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div> <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div> <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div> <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div> <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div> <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div> <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div> </div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number\" lesson1-número-verde\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">spielen — jugar; jugar</div> <div class=\"course-example\">nein - no</div> <div class=\"course-example\">nicht - no</div> <div class=\"kurss-example\">nein — trabajar</div> <div class=\"kurss-example\">nicht — preguntar</div> <div class=\"kurss-example\">arbeiten — was tut er? ¿Qué está haciendo?</div> <div class=\"kurss-example\">fragen — ¿qué hacen ellos?</div> <div class=\"curso-example\">aber - pero</div> <div class=\"kurss-example\">was tut er? — responder</div> <div class=\"kurss-example\">was tun sie? — calcular</div> <div class=\"kurss-example\">aber — dibujar</div> <div class=\"kurss-example\">antworten — Marie</div> </div> </div> </details> <details class=\"lesson1-acordeón\"> <summary><span class=\"lesson1-number\" lesson1-número-púrpura\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">rechnen — En las palabras ich, nicht, rechnen, zeichnen, el sonido ch se pronuncia suavemente, aproximadamente como en las palabras letonas: technika, Frīdrihs.</div><div class=\"kurss-example\">zeichnen — En las palabras arbeiten, zeichnen, el diptongo ei se pronuncia aproximadamente como el sonido e bemol letón seguido de i.</div><div class=\"kurss-example\">Marie — El grupo de consonantes sp se pronuncia como šp: spielen (špīlen).</div><div class=\"kurss-example\">Vārdos ich, nicht, rechnen, zeichnen skaņu ch izrunā mīksti, apmēram tā, kā latviski vārdos: technika, Frīdrihs.</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-número-azul\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>1</span>Terminaciones con e</h4> <div class=\"lesson1-grammar-note\">Si la raíz del verbo termina en t, d, chn, entonces las terminaciones -st y -t están precedidas por e.</div> <h5 class=\"lesson2-subtitle\">arbeiten</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">ich arbeite</div><div class=\"course-example\">du arbeite</div><div class=\"course-example\">er Arbeit</div><div class=\"course-example\">sie arbeit</div><div class=\"course-example\">wir arbeiten</div><div class=\"course-example\">mi arbeit</div><div class=\"course-example\">sie arbeiten</div></div> <h5 class=\"lesson2-subtitle\">rechnen</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">ich rechne</div><div class=\"course-example\">du rechnest</div><div class=\"course-example\">er rechnet</div><div class=\"course-example\">sie rechnet</div><div class=\"course-example\">nosotros rechnen</div><div class=\"course-example\">ihr rechnet</div><div class=\"course-example\">sie rechnen</div></div> <h5 class=\"lesson2-subtitle\">tun</h5> <div class=\"lesson1-card-grid\"><div class=\"course-example\">ich tue</div><div class=\"course-example\">du tust</div><div class=\"course-example\">er tut</div><div class=\"course-example\">sie tut</div><div class=\"course-example\">wir tun</div><div class=\"course-example\">ihr tut</div><div class=\"course-example\">sie tun</div></div> </section> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>2</span>Palabra en cuestión</h4> <div class=\"lesson1-grammar-note\">En oraciones interrogativas que comienzan con la palabra interrogativa, por ejemplo: ¿qué? ¿qué? ¿OMS? ¿por qué? ¿por qué? etc., el verbo está inmediatamente después de la palabra interrogativa.</div> <div class=\"lesson1-card-grid\"><div class=\"course-example\">¿Fue tust du? - ¿Qué estás haciendo?</div><div class=\"kurss-example\">Vārdos arbeiten, zeichnen divskani ei izrunā apmēram kā latviešu plato e skaņu, kam seko i.</div><div class=\"kurss-example\">Līdzskaņu kopojumu sp izrunā kā šp: spielen (špīlen).</div><div class=\"kurss-example\">Darbības vārdā tun u izrunājams gari visās personās.</div></div> </section> <section class=\"lesson1-block\"> <h4 class=\"lesson1-grammar-header\"><span>3</span>Negación con nicht</h4> <div class=\"lesson1-grammar-note\">Si la negación nicht se refiere a un verbo, entonces la palabra negada viene después del verbo.</div> <div class=\"lesson1-card-grid\"><div class=\"course-example\">Er kommt nicht. — No viene.</div><div class=\"kurss-example\">ich arbeite</div></div> </section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-training-wrap\"> <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de traducción de la lección 2\"> <span class=\"lesson1-training-progress\">Conferencia 2 · Traducido: 1 / 15</span> <span class=\"lesson1-training-text\">¿Quién pregunta?</span> </button> <p class=\"lesson1-training-hint\">Haz clic en la card para ver el alemán traducción. Después de la respuesta, el siguiente clic muestra la siguiente card.</p> </div> </div> </details>",
  "kurssLesson6": "<h3>Lección 6</h3> <p class=\"kurss-lesson-intro\">Números, plurales, diéresis y formas plurales de sustantivos.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — es, es, mentiras</div><div class=\"kurss-example\">der Bleistift (bleištift) — lápiz</div><div class=\"kurss-example\">einige (einige) — some</div><div class=\"kurss-example\">hinlegen — poner abajo</div><div class=\"kurss-example\">legt hin — dejar</div><div class=\"kurss-example\">wieder (vīder) — otra vez</div><div class=\"kurss-example\">aufmachen — desatar</div><div class=\"kurss-example\">er macht auf — desata</div><div class=\"kurss-example\">anspitzen (anšpicen) — escupir</div><div class=\"kurss-example\">er spitzt an — escupe</div><div class=\"kurss-example\">sich setzen — sentarse</div><div class=\"kurss-example\">setzt sich — se sienta</div><div class=\"kurss-example\">der Schlüssel (šlūsel) — llave</div><div class=\"kurss-example\">das Fenster (fenster) — ventana</div><div class=\"kurss-example\">die Tafel (dī tāfel) — pizarra</div><div class=\"kurss-example\">der Garten — jardín</div><div class=\"kurss-example\">der Löffel — cuchara</div><div class=\"kurss-example\">zählen (cēlen) — contar</div><div class=\"kurss-example\">die Nadel — aguja</div><div class=\"kurss-example\">was ist das — ¿Qué es?</div><div class=\"kurss-example\">der Hammer — mazo</div><div class=\"kurss-example\">die Hämmer — mazo</div><div class=\"kurss-example\">der Deckel (dēr dekel) — tapa</div><div class=\"kurss-example\">der Teller — plato</div><div class=\"kurss-example\">der Wagen — carro</div><div class=\"kurss-example\">der Schlitten — trineo, trineo</div><div class=\"kurss-example\">das Ding — cosa</div><div class=\"kurss-example\">die Dinge — cosas</div><div class=\"kurss-example\">wie sind die Dinge? — ¿Cuáles son las cosas?</div><div class=\"kurss-example\">voll (fōl) — full</div><div class=\"kurss-example\">leer (lēr) — vacío</div><div class=\"kurss-example\">schwer (švēr) — pesado, difícil</div><div class=\"kurss-example\">leicht — ligero</div><div class=\"kurss-example\">der Eimer — cubo</div><div class=\"kurss-example\">wieviel (vīfīl) — cuántos</div><div class=\"kurss-example\">wieviel Nadeln — cuántos agujas</div><div class=\"kurss-example\">hier (hīr) — aquí</div><div class=\"kurss-example\">dort — allá</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä ir patskaņa a pārskanojums, un to izrunā kā īso vai garo šauro e.</div><div class=\"kurss-example\">Piemēri: das Mädchen (mētchen), die Bänke (dī benke), der Vater (dēr fāter), die Väter (dī fēter).</div><div class=\"kurss-example\">ü ir patskaņa u pārskanojums. To izrunājot, lūpas ļoti jāapaļo un jāmēģina ar apaļi veidotām lūpām izrunāt i.</div><div class=\"course-example\">Ejemplos: fünf, der Schlüssel (schlüsel).</div><div class=\"course-example\">pronunciar ö con labios redondeados, tratando de pronunciar e: der Löffel.</div><div class=\"course-example\">Una vocal doble representa una vocal larga: leer.</div><div class=\"curso-ejemplo\">A doubled eu se pronuncia como oi: neun (noin).</div></div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramática y explicaciones</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Piemēri: fünf, der Schlüssel (šlūsel).</div><div class=\"kurss-example\">ö izrunā ar apaļi veidotām lūpām, mēģinot izrunāt e: der Löffel.</div><div class=\"kurss-example\">Divkāršots patskanis apzīmē garu patskani: leer (lēr).</div><div class=\"kurss-example\">Divskani eu izrunā kā oi: neun (noin).</div><div class=\"kurss-example\">Salikta darbības vārda uzsvērtais priedēklis tagadnē atdalās no darbības vārda un stāv teikuma beigās.</div><div class=\"kurss-example\">Piemēri: hinlegen — Satiana en alemán tiene una forma singular y plural: der Schüler ist pequeño; die Schüler sind klein.</div><div class=\"kurss-example\">Skaitļa vārds viens ir visās trīs kārtās, ja to lieto ar lietvārdu: vīriešu kārtā ein, sieviešu kārtā eine, vidējā kārtā ein.</div><div class=\"kurss-example\">Piemēri: ein Schüler — das ist ein Hammer; es una aguja: das ist eine Nadel; son martillos—das sind Hämmer; son agujas - das sind Nadeln.</div><div class=\"kurss-example\">Skaitļi: eins, zwei, drei, vier (fīr), fünf, sechs (zeks), sieben (zīben), acht, neun (noin), zehn (cēn).</div><div class=\"kurss-example\">Saitaiņa vācu valodā ir vienskaitļa un daudzskaitļa forma: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Norādāmais vietniekvārds tas latviešu valodā mainās skaitlī un kārtā, bet vācu valodā lieto vienu formu: das.</div><div class=\"kurss-example\">Piemēri: tas ir veseris — el, -er plural toma -n.</div><div class=\"kurss-example\">Der Wagen — die Nadeln; morir Feder - morir Federn.</div><div class=\"kurss-example\">Vīriešu un vidējās kārtas lietvārdi ar galotni -die Mütter (madres); die Tochter (hija) — die Töchter (hijas).</div><div class=\"kurss-example\">Piemēri: der Hammer — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">Sieviešu kārtas lietvārdi ar galotni -En una oración narrativa, el verbo predicado ocupa el segundo lugar: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lección 6 card de traducción\"><span class=\"lesson1-training-progress\">Lección 6 · Traducir: 1 / 21</span><span class=\"lesson1-training-text\">Paul toma un lápiz y dibuja.</span></button><p class=\"lesson1-training-hint\">Haga clic en las cards para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div> </details>",
  "kurssLesson5": "<h3>Lección 5</h3> <p class=\"kurss-lesson-intro\">Wen?, acusativo, sitzen, fragen y terminación -in.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div> <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div> <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div> <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div> <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div> <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div> <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div> <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div> <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div> <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div> <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div> <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">sitzen (zicen) — sentarse</div> <div class=\"kurss-example\">fragen (frāgen) — preguntar</div> <div class=\"kurss-example\">der Lehrer (dēr lērer) — profesor</div> <div class=\"kurss-example\">gut (gūt) — bueno</div> <div class=\"kurss-example\">wen (vēn) — qué</div> <div class=\"kurss-example\">loben — elogio</div> <div class=\"kurss-example\">der Schüler (šūler) — estudiante</div> <div class=\"kurss-example\">klein — pequeño</div> <div class=\"kurss-example\">groß (grōs) — grande</div> <div class=\"kurss-example\">die Lehrerin — maestra</div> <div class=\"kurss-example\">die Schülerin — colegiala</div> <div class=\"kurss-example\">schlecht (šleht) — malo</div> <div class=\"kurss-example\">tadeln — pelt</div> <div class=\"kurss-example\">oder (ōder) — or</div> <div class=\"kurss-example\">das Kind (kint) — niño</div> <div class=\"kurss-example\">artig (ārtich) — educado</div> <div class=\"kurss-example\">die Mutter — madre</div> <div class=\"kurss-example\">lieben (līben) — amar</div> <div class=\"kurss-example\">der Vater (fāter) — padre</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"> <div class=\"kurss-example\">tz ir dubultots z skanis un izrunājams kā z: sitzen (zicen).</div> <div class=\"kurss-example\">v vācu vārdos izrunā kā f: der Vater (fāter).</div> <div class=\"kurss-example\">ß sauc par escet un izrunā kā latviešu s: groß (grōs), weiß (veis).</div> </div></div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativo y acusativo</h4><div class=\"lesson1-grammar-note\">En español, el nominativo responde a la pregunta ¿quién? y el acusativo responde a la pregunta ¿qué?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vācu valodā nominatīvā jautājums ir wer? personām un was? priekšmetiem.</div><div class=\"kurss-example\">Akuzatīvā jautājums ir wen? personām un was? priekšmetiem.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Cambiar artículos al acusativo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"course-example\">sie sitzen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + acusativo</h4><div class=\"lesson1-grammar-note\">El verbo fragen en alemán requiere un acusativo.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sie sitzen</div><div class=\"kurss-example\">Wen fragt der Lehrer?</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">finalización -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div><div class=\"kurss-example\">Daudz sieviešu kārtas vārdu atvasina ar galotni -die Lehrerin</div><div class=\"kurss-example\">die Lehrerin</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Lugar del verbo</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">die Schülerin</div><div class=\"kurss-example\">Stāstāmā teikumā darbības vārds stāv otrā vietā.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de traducción de la Lección 5\"><span class=\"lesson1-training-progress\">Lección 5 · Traducir: 1 / 16</span><span class=\"lesson1-training-text\">¿Qué ama el padre?</span></button><p class=\"lesson1-training-hint\">Haga clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div> </details>",
  "kurssLesson4": "<h3>Lección 4</h3> <p class=\"kurss-lesson-intro\">Acusativo, nehmen, hinlegen, hinausgehen y adjetivos.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-número-verde\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">nehmen (nēmen) - tomar</div><div class=\"course-example\">er nimmt (nimt) — toma</div><div class=\"kurss-example\">nehmen (nēmen) — emplumado</div><div class=\"kurss-example\">er nimmt (nimt) — emplumado</div><div class=\"kurss-example\">der Federhalter (dēr fēderhalter) — show</div><div class=\"kurss-example\">einen Federhalter — negro</div><div class=\"kurss-example\">zeigen — blanco</div><div class=\"kurss-example\">schwarz (švarc) — pluma</div><div class=\"kurss-example\">weiß (veis) — pluma</div><div class=\"kurss-example\">die Feder (dī fēder) — puntiagudo</div><div class=\"kurss-example\">eine Feder — dejar</div><div class=\"kurss-example\">spitz (špic) — dejar</div><div class=\"kurss-example\">hinlegen — niña</div><div class=\"kurss-example\">legt hin — cuchillo</div><div class=\"kurss-example\">das Mädchen (mētchen) — cuchillo</div><div class=\"kurss-example\">das Messer — agudo</div><div class=\"kurss-example\">ein Messer — contundente</div><div class=\"kurss-example\">scharf — luego</div><div class=\"kurss-example\">stumpf (štumpf) — afuera</div><div class=\"kurss-example\">dann — sal, ve out</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinaus — en, -er, -el no están acentuadas, por lo que la e en estos extremos es apenas audible: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">hinausgehen — h en alemán puede ser tanto un sonido como un marcador de longitud para la vocal anterior.</div><div class=\"kurss-example\">Galotnes -Si h es un marcador de longitud, no se pronuncia como un sonido: nehmen (nēmen).</div><div class=\"kurss-example\">h vācu valodā var būt gan skaņa, gan garumzīme iepriekšējam patskanim.</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-número-azul\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Acusativo</h4><div class=\"lesson1-grammar-note\">En femenino y neutro, el acusativo es igual al nominativo. Sólo los hombres cambian de ronda.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ja h ir garumzīme, to neizrunā kā skaņu: nehmen (nēmen).</div><div class=\"kurss-example\">Ja patskanim seko tikai viens līdzskanis, patskani izrunā gari: die (dī) Feder (fēder), den (dēn).</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"course-example\">ich nehme</div><div class=\"course-example\">du nimmst</div><div class=\"course-example\">er/sie nimmt</div><div class=\"course-example\">wir nehmen</div><div class=\"course-example\">ihr nehmt</div><div class=\"course-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronombres</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbos separables</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjetivos</h4><div class=\"lesson1-grammar-note\">Si un adjetivo es un adjetivo en una oración, no cambia en orden ni número.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div><div class=\"kurss-example\">er — das Messer ist klein</div><div class=\"kurss-example\">sie — die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negación con nicht</h4><div class=\"lesson1-grammar-note\">Si nicht niega un adjetivo, se coloca delante de la palabra negativa.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">es — der Federhalter ist nicht weiß</div><div class=\"kurss-example\">daudzskaitlī — das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Conferencia 4 card de traducción\"><span class=\"lesson1-training-progress\">Lección 4 · Traducir: 1 / 16</span><span class=\"lesson1-training-text\">La niña toma un eje de pluma.</span></button><p class=\"lesson1-training-hint\">Haga clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div></details>",
  "kurssLesson3": "<h3>Lección 3</h3> <p class=\"kurss-lesson-intro\">La tercera conferencia: diálogos, palabras, pronunciación, gramática y traducción.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">wer - qué</div><div class=\"course-example\">era - qué</div><div class=\"kurss-example\">wer — aquí</div><div class=\"kurss-example\">was — allí</div><div class=\"kurss-example\">hier — der Tisch table</div><div class=\"kurss-example\">dort — mesa</div><div class=\"kurss-example\">der Tisch — banco</div><div class=\"kurss-example\">ein Tisch — banco</div><div class=\"kurss-example\">die Bank — tumbado</div><div class=\"kurss-example\">eine Bank — ¿hay/hay un libro aquí?</div><div class=\"kurss-example\">liegen — un libro</div><div class=\"kurss-example\">liegt hier ein Buch? — un libro</div><div class=\"kurss-example\">das Buch — hang</div><div class=\"kurss-example\">ein Buch — imagen</div><div class=\"kurss-example\">hängen — imagen</div><div class=\"kurss-example\">das Bild — pizarra</div><div class=\"kurss-example\">ein Bild — pizarra</div><div class=\"kurss-example\">die Tafel — alguien, qué</div><div class=\"kurss-example\">eine Tafel — es</div><div class=\"kurss-example\">wie — grueso, gordo</div><div class=\"kurss-example\">ist — cuaderno</div><div class=\"kurss-example\">dick — cuaderno</div><div class=\"kurss-example\">das Heft — delgado, delgado</div><div class=\"kurss-example\">ein Heft — bajo</div><div class=\"kurss-example\">dünn — alto</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">niedrig — El sonido ī largo en alemán está representado por ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">hoch — ck es doble k: dick (dikk).</div><div class=\"kurss-example\">Garo ī skaņu vācu valodā apzīmē ar ie: liegen (līgen), hier (hīr), wie (vī).</div><div class=\"kurss-example\">ck ir divkāršs k: dick (dikk).</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Sujeto de la oración</h4><div class=\"lesson1-grammar-note\">El sujeto de una oración en alemán responde a la pregunta wer? / ¿qué? y nominativo permanente.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Īpašības un apstākļu vārdos galotne -¿Con wer? pregunta por personas.</div><div class=\"kurss-example\">Ja galotne -¿Ar qué? pregunta por temas.</div><div class=\"kurss-example\">Ar wer? jautā pēc personām.</div><div class=\"kurss-example\">Ar was? jautā pēc priekšmetiem.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artículos</h4><div class=\"lesson1-grammar-note\">En el idioma alemán, el sustantivo tiene 3 casos: masculino, femenino y neutro. Los sustantivos suelen ir precedidos de una palabra llamada article. Esta palabra no está traducida.</div><h5 class=\"lesson2-subtitle\">Noteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer singt? — der</div><div class=\"kurss-example\">Was liegt hier? — die</div><div class=\"kurss-example\">vīriešu kārta — das</div><div class=\"kurss-example\">sieviešu kārta — Plural definido el article para las tres rondas es morir.</div><div class=\"kurss-example\">vidējā kārta — die Tische</div><div class=\"kurss-example\">Daudzskaitlī noteiktais artikuls visām trim kārtām ir die.</div><div class=\"kurss-example\">der Tisch — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Nenoteiktais artikuls</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">die Bank — ein</div><div class=\"kurss-example\">das Heft — eine</div><div class=\"kurss-example\">vīriešu kārta — ein</div><div class=\"kurss-example\">sieviešu kārta — El indefinido el article no tiene plural.</div><div class=\"kurss-example\">vidējā kārta — Tische</div><div class=\"kurss-example\">Nenoteiktajam artikulam daudzskaitļa nav.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Sustantivos propios</h4><div class=\"lesson1-grammar-note\">Sin artículos delante de nombres propios.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ein Tisch — Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Lugar del verbo</h4><div class=\"lesson1-grammar-note\">En una oración narrativa, el verbo ocupa el segundo lugar.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ein Heft — Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.<br><br></div><div class=\"kurss-example\">Hier hängt eine Karte.<br><br></div><div class=\"kurss-example\">Vāciski par priekšmetiem, kas stāv vertikāli, saka, ka priekšmets stāv:<br>der Tisch steht<br>die Bank steht</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-número-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de traducción de la lección 3\"><span class=\"lesson1-training-progress\">Lección 3 · Traducir: 1 / 22</span><span class=\"lesson1-training-text\">¿Cuentas?</span></button><p class=\"lesson1-training-hint\">Haz clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p></div></div></details>",
  "kurssLesson7": "<h3>Lección 7</h3> <p class=\"kurss-lesson-intro\">Séptima lección: expresión de mando, forma de dirección y plural.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Diálogos/oraciones</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">Hans, singe ein Lied! ¿Qué estás haciendo? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div></div></div> </details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"course-example\">singen — cantar</div><div class=\"course-example\">singe — cantar</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div><div class=\"kurss-example\">singen — cantar</div><div class=\"kurss-example\">singe — canción</div><div class=\"kurss-example\">singt — Tú</div><div class=\"kurss-example\">singen Sie — conde</div><div class=\"kurss-example\">das Lied (das līt) — jovencita</div><div class=\"kurss-example\">Sie — molinero</div><div class=\"kurss-example\">zählen — abierto</div><div class=\"kurss-example\">das Fräulein (froilein) — ventana</div><div class=\"kurss-example\">der Müller — todos</div><div class=\"kurss-example\">öffnen — espejo</div><div class=\"kurss-example\">das Fenster (fenster) — trapo, fregona</div><div class=\"kurss-example\">alle — pala</div><div class=\"kurss-example\">der Spiegel (špīgel) — escoba</div><div class=\"kurss-example\">der Lappen — pala</div><div class=\"kurss-example\">der Spaten — cuenco</div><div class=\"kurss-example\">der Besen — habitación</div><div class=\"kurss-example\">die Schaufel — orilla</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">die Schüssel — sp al principio de una palabra o sílaba se pronuncia como šp: der Spiegel (para špīgel).</div><div class=\"kurss-example\">das Zimmer — sch se pronuncia como letón š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">das Ufer (ūfer) — El diptongo äu se pronuncia como letón oi: das Fräulein (das froilein).</div></div></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Expresión de comandos</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp vārda vai zilbes sākumā izrunā kā šp: der Spiegel (dēr špīgel).</div><div class=\"kurss-example\">sch izrunā kā latviešu š: die Schaufel (dī šaufel), die Schüssel (dī šūsel).</div><div class=\"kurss-example\">Divskani äu izrunā kā latviešu oi: das Fräulein (das froilein).</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Comando plural</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pavēles izteiksme vienskaitļa 2. personā atbilst darbības vārda 2. personai vienskaitlī bez personu galotnes -La forma del comando en la segunda persona del plural es similar a la segunda persona del presente plural, pero se usa sin pronombre.</div><div class=\"kurss-example\">Piemēri: antworte!, arbeite!, öffne!, zeichne!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Forma de tratamiento con Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ļoti bieži galotne -La forma de tratamiento con \"Usted\" se parece a la tercera persona del plural. El pronombre Sie es escrito con mayúscula y después del verbo.</div><div class=\"kurss-example\">Pavēles forma 2. personā daudzskaitlī līdzinās tagadnes daudzskaitļa 2. personai, bet tiek lietota bez vietniekvārda.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Piemēri: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section></div></details> <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Ejercicio</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de ejercicios de la lección 7\"><span class=\"lesson1-training-progress\">Lección 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen - preguntar</span></button><p class=\"lesson1-training-hint\">Toque la card para ver los formularios de comando.</p></div></div></details>",
  "kurssLesson1": "<h3>Lección 1</h3> <p class=\"kurss-lesson-intro\">Primera lección: verbos en presente, sustantivos, pronunciación, gramática y traducción.</p> <details class=\"lesson1-accordion\" open> <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbos en presente</span><span class=\"lesson1-chevron\">⌃</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-info\">Verbos y sus conjugaciones en tiempo presente.</div> <div class=\"lesson1-verb-cards\"> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — venir</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>yo vengo</span><span>du</span><strong>kommst</strong><span>tú vienes</span><span>er / sie</span><strong>kommt</strong><span>él / ella viene</span><span>wir</span><strong>kommen</strong><span>nosotros ven</span><span>ihr</span><strong>kommt</strong><span>tú vienes</span><span>sie / Sie</span><strong>kommen</strong><span>ellos / tú vienes</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — go</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>yo voy</span><span>du</span><strong>gehst</strong><span>tú vas</span><span>er / sie</span><strong>geht</strong><span>he / ella va</span><span>wir</span><strong>gehen</strong><span>nosotros vamos</span><span>ihr</span><strong>geht</strong><span>tú ejat</span><span>sie / Sie</span><strong>gehen</strong><span>ellos / tú vas</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — pararse</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>I stand</span><span>du</span><strong>stehst</strong><span>tú estás de pie</span><span>er / sie</span><strong>steht</strong><span>él / ella está de pie</span><span>wir</span><strong>stehen</strong><span>nosotros estamos de pie</span><span>ihr</span><strong>steht</strong><span>tú estás de pie</span><span>sie / Sie</span><strong>stehen</strong><span>ellos / Tú estás</span></div> </article> <article class=\"lesson1-verb-card\"> <h4><span class=\"lesson1-verb-icon\">♟</span>singen — to canta</h4> <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>yo canto</span><span>du</span><strong>singst</strong><span>tú cantas</span><span>er / sie</span><strong>singt</strong><span>él / ella canta</span><span>wir</span><strong>singen</strong><span>nosotros cantamos</span><span>ihr</span><strong>singt</strong><span>tú cantas</span><span>sie / Sie</span><strong>singen</strong><span>ellos / tú cantas</span></div> </article> </div> <section class=\"lesson1-block\"> <h4>Ejemplos</h4> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div> </section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Palabras</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>El La pronunciación aproximada de las palabras se da entre paréntesis con letras letonas.<br>Esto también debería seguirse en futuras conferencias.</span></div> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vīr) — we</div><div class=\"kurss-example\">Vārdā “wir” burts i tiek izrunāts gari.</div><div class=\"kurss-example\">kommen (komen) — venir</div><div class=\"kurss-example\">gehen (gē-en) - ir</div><div class=\"kurss-example\">stehen (štē-en) - stand</div><div class=\"kurss-example\">singen (zingen) — canta</div><div class=\"kurss-example\">du (dū) kommst — tú vienes</div><div class=\"kurss-example\">er (ēr) kommt — él viene</div><div class=\"kurss-example\">sie (zī) kommt — ella viene</div><div class=\"kurss-example\">wer (vēr) — ¿qué?</div><div class=\"kurss-example\">ja (jā) — sí</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number\" lesson1-número-purple\">3.</span><span>Pronunciación</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Vārdu pareiza izruna, apzīmēta latviešu burtiem, ir dota lekcijās.</div><div class=\"kurss-example\">Wir (vīr) — nosotros La palabra wir siempre se pronuncia larga.</div></div> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramática</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content lesson1-grammar-content\"> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitivo</h4><div class=\"lesson1-grammar-note\">La forma base de un verbo. Normalmente el infinitivo termina en -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Presente terminaciones</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Eliminar <span class=\"lesson1-ending-accent\">-en</span> de las formas base del verbo y agrega la terminación.</strong></p><p>Ejemplo: kommen → komm + terminación</p><div class=\"lesson1-ending-process\" aria-label=\"El proceso de formar la terminación presente\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma base</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>eliminar <span class=\"lesson1-ending-accent\">-es</span></strong><span>la raíz permanece</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>raíz</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>end</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"course-example\">ich → -e</div><div class=\"course-example\">du → -st</div><div class=\"course-example\">er / sie → -t</div><div class=\"course-example\">wir → -en</div><div class=\"course-example\">ihr → -t</div><div class=\"course-example\">sie → -en</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Ejemplos</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -ich komme</div><div class=\"kurss-example\">du → -du kommst</div><div class=\"kurss-example\">er / sie → -er kommt</div><div class=\"kurss-example\">wir → -wir kommen</div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Oraciones de preguntas</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>En una oración de preguntas en alemán, el verbo generalmente se mueve a la primera posición.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ihr → -En letón:<br><br></div><div class=\"kurss-example\">sie → -Alemán en:<br><br></div><div class=\"kurss-example\">ich komme<br></div><div class=\"kurss-example\">du kommst<br></div></div></section> <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Diferencia de persona</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div><div class=\"kurss-example\">Latviešu valodā:<br>Tu nāc.<br>Vai tu nāc?</div></div></section> </div> </details> <details class=\"lesson1-accordion\"> <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Traducir</span><span class=\"lesson1-chevron\">⌄</span></summary> <div class=\"lesson1-content\"> <div class=\"lesson1-training-wrap\"> <button class=\"lesson1-training-flashcard\" tipo=\"botón\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"card de entrenamiento de la Lección 1\"> <span class=\"lesson1-training-progress\">Lección 1 · Traducido: 1 / 11</span> <span class=\"lesson1-training-text\">¿Vienes?</span> </button> <p class=\"lesson1-training-hint\">Haz clic en la card para ver la traducción al alemán. Después de la respuesta, el siguiente clic muestra la siguiente card.</p> </div> </div> </details>"
};

