          "wieviel — cik",
          "Max (maks) — Maksis",
          "groß — mentiras",
          "klein — mazs",
          "kleiner als ich — más pequeño que yo",
          "alt — vecs",
          "jung — amarillos",
          "jünger als ich — más joven que yo",
